import crypto from 'node:crypto';

import type { RefreshTokenRecord, User } from '../types/auth.js';

const users = new Map<string, User>();
const usersByEmail = new Map<string, string>();
const usersByGoogleId = new Map<string, string>();
const refreshTokens = new Map<string, RefreshTokenRecord>();

export interface CreateUserInput {
  email: string;
  passwordHash: string;
  firstName: string;
  lastName: string;
  role: User['role'];
  departmentId?: string;
  googleId?: string;
  googleRefreshToken?: string;
}

export interface UpdateUserInput {
  email?: string;
  firstName?: string;
  lastName?: string;
  role?: User['role'];
  departmentId?: string;
  googleId?: string;
  googleRefreshToken?: string;
}

export const userRepository = {
  async create(input: CreateUserInput) {
    const now = new Date().toISOString();
    const user: User = {
      id: crypto.randomUUID(),
      ...input,
      createdAt: now,
      updatedAt: now,
    };

    users.set(user.id, user);
    usersByEmail.set(user.email, user.id);
    if (user.googleId) usersByGoogleId.set(user.googleId, user.id);

    return user;
  },

  async findByEmail(email: string) {
    const id = usersByEmail.get(email);
    return id ? users.get(id) : undefined;
  },

  async findById(id: string) {
    return users.get(id);
  },

  async findByGoogleId(googleId: string) {
    const id = usersByGoogleId.get(googleId);
    return id ? users.get(id) : undefined;
  },

  async list(filters?: { search?: string; role?: User['role']; departmentId?: string }) {
    const search = filters?.search?.trim().toLowerCase();

    return [...users.values()].filter((user) => {
      const matchesSearch =
        !search ||
        [user.email, user.firstName, user.lastName, user.role, user.departmentId ?? '']
          .join(' ')
          .toLowerCase()
          .includes(search);
      const matchesRole = !filters?.role || user.role === filters.role;
      const matchesDepartment = !filters?.departmentId || user.departmentId === filters.departmentId;

      return matchesSearch && matchesRole && matchesDepartment;
    });
  },

  async update(id: string, input: UpdateUserInput) {
    const existing = users.get(id);

    if (!existing) {
      return undefined;
    }

    if (input.email && input.email !== existing.email) {
      usersByEmail.delete(existing.email);
      usersByEmail.set(input.email, id);
    }

    if (input.googleId && input.googleId !== existing.googleId) {
      if (existing.googleId) usersByGoogleId.delete(existing.googleId);
      usersByGoogleId.set(input.googleId, id);
    }

    const updated: User = {
      ...existing,
      ...input,
      updatedAt: new Date().toISOString(),
    };

    users.set(id, updated);

    return updated;
  },

  async delete(id: string) {
    const existing = users.get(id);

    if (!existing) {
      return false;
    }

    users.delete(id);
    usersByEmail.delete(existing.email);
    if (existing.googleId) usersByGoogleId.delete(existing.googleId);

    return true;
  },

  async createRefreshToken(input: Omit<RefreshTokenRecord, 'id' | 'createdAt'>) {
    const record: RefreshTokenRecord = {
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      ...input,
    };

    refreshTokens.set(record.id, record);
    return record;
  },

  async findRefreshTokenByHash(tokenHash: string) {
    return [...refreshTokens.values()].find((record) => record.tokenHash === tokenHash);
  },

  async revokeRefreshToken(id: string, replacedByTokenId?: string) {
    const existing = refreshTokens.get(id);

    if (!existing) {
      return;
    }

    refreshTokens.set(id, {
      ...existing,
      revokedAt: new Date().toISOString(),
      replacedByTokenId,
    });
  },
};

